"""Registry of grades by student."""

_ALL = []
_BY_KEY = None


def reset():
    """Forget every registered grade."""
    global _BY_KEY
    del _ALL[:]
    _BY_KEY = None


def register(grade):
    """Add one grade to the registry."""
    _ALL.append(grade)


def find(student):
    """Return the grades registered under this student."""
    global _BY_KEY
    if _BY_KEY is None:
        _BY_KEY = {}
        for x in _ALL:
            _BY_KEY.setdefault(x.student, []).append(x)
    return _BY_KEY.get(student, [])


def student_names(grades):
    """Return the distinct student values, in first-seen order."""
    names = []
    for x in grades:
        if x.student not in names:
            names.append(x.student)
    return names

